import {$,findPath} from './core.js';
const W=18,H=12;let walls=new Set([43,61,79,97,115,133,151,169]),start=37,end=178,running=false,runId=0;
$('#app').innerHTML=`<div class="toolbar"><label>Algorithm<select id="algorithm"><option value="bfs">Breadth-first search</option><option value="dfs">Depth-first search</option></select></label><label>Click to place<select id="paint"><option value="wall">Wall / erase wall</option><option value="start">Start point</option><option value="end">End point</option></select></label><label>Animation speed<select id="speed"><option value="18">Steady</option><option value="5">Fast</option><option value="0">Instant</option></select></label><button id="run">Find a route →</button><button id="clear" class="secondary">Clear grid</button></div><div class="legend"><span style="--color:#5b7bbb">Start</span><span style="--color:#b55c58">Destination</span><span style="--color:#263d32">Wall</span><span style="--color:#b5d9bf">Visited</span><span style="--color:#e7bc56">Path</span></div><div class="panel"><div class="board" id="board" aria-label="Pathfinding grid"></div></div><p class="small">Click a cell or use Tab and Enter. Change the placement tool to move the start or destination.</p><div class="grid two"><div class="panel"><span class="eyebrow">Nodes explored</span><div id="explored" class="metric">—</div></div><div class="panel"><span class="eyebrow">Path length · steps</span><div id="length" class="metric">—</div></div></div>`;
function render(){ $('#board').innerHTML=Array.from({length:W*H},(_,i)=>`<button class="cell ${walls.has(i)?'wall':i===start?'start':i===end?'end':''}" data-cell="${i}" aria-label="Row ${Math.floor(i/W)+1}, column ${i%W+1}: ${walls.has(i)?'wall':i===start?'start':i===end?'destination':'open'}"></button>`).join('')}
$('#board').onclick=e=>{if(running||!e.target.matches('[data-cell]'))return;const n=Number(e.target.dataset.cell),mode=$('#paint').value;if(mode==='start'&&n!==end){start=n;walls.delete(n)}else if(mode==='end'&&n!==start){end=n;walls.delete(n)}else if(mode==='wall'&&n!==start&&n!==end){walls.has(n)?walls.delete(n):walls.add(n)}render();$('#board').children[n]?.focus()};
$('#clear').onclick=()=>{runId++;running=false;$('#run').disabled=false;walls.clear();render();$('#status').textContent='Grid cleared.';$('#explored').textContent='—';$('#length').textContent='—'};
$('#run').onclick=async()=>{running=true;const id=++runId;$('#run').disabled=true;render();const result=findPath(W,H,walls,start,end,$('#algorithm').value),cells=$('#board').children;const speed=matchMedia('(prefers-reduced-motion: reduce)').matches?0:Number($('#speed').value);let count=0;for(const n of result.visited){if(id!==runId)return;if(n!==start&&n!==end)cells[n].classList.add('visited');$('#explored').textContent=String(++count);if(speed)await new Promise(r=>setTimeout(r,speed))}if(id!==runId)return;for(const n of result.path){if(n!==start&&n!==end)cells[n].classList.add('path')}$('#length').textContent=result.path.length?result.path.length-1:'No route';$('#status').textContent=result.path.length?`${$('#algorithm').value==='bfs'?'Shortest route found.':'Route found; DFS does not guarantee the shortest route.'} ${result.path.length-1} steps.`:'No route exists. Remove some walls and try again.';running=false;$('#run').disabled=false};render();
